import React, { useState } from 'react';
import '../pages/Carrito.css'; // Asegúrate que esta ruta esté bien

function Carrito() {
  const [cart, setCart] = useState([
    {
      id: 1,
      name: 'Samsung S23+',
      priceOriginal: 280000,
      priceOffer: 190000,
      image: 'https://via.placeholder.com/100',
      quantity: 1,
    },
    {
      id: 2,
      name: 'iPhone 14 Pro Max',
      priceOriginal: 920000,
      priceOffer: 920000,
      image: 'https://via.placeholder.com/100',
      quantity: 1,
    }
  ]);
  const [coupon, setCoupon] = useState('');

  const removeFromCart = (id) => {
    setCart(cart.filter(product => product.id !== id));
  };

  const clearCart = () => {
    setCart([]);
  };

  const handleCheckout = () => {
    alert('¡Compra confirmada!');
    clearCart();
  };

  const subtotal = cart.reduce((acc, product) => acc + (product.priceOffer * product.quantity), 0);
  const discount = 40000; // descuento fijo
  const total = subtotal - discount;

  return (
    <div className="carrito-container">
      <h2>Mi Carrito</h2>
      <div className="carrito-content">

        {/* Productos */}
        <div className="cart-items">
          {cart.length > 0 ? cart.map(product => (
            <div key={product.id} className="cart-item">
              <img src={product.image} alt={product.name} className="item-image" />
              <div className="item-details">
                <h3>{product.name}</h3>
                <div className="item-prices">
                  <span className="original-price">${product.priceOriginal.toLocaleString()}</span>
                  <span className="offer-price">${product.priceOffer.toLocaleString()}</span>
                </div>
                <div className="item-quantity">
                  <label>Cantidad:</label>
                  <input type="number" value={product.quantity} min="1" readOnly />
                </div>
              </div>
              <button onClick={() => removeFromCart(product.id)} className="remove-btn">Eliminar</button>
            </div>
          )) : (
            <p className="empty-cart">Tu carrito está vacío</p>
          )}

          {cart.length > 0 && (
            <button onClick={clearCart} className="clear-btn">Vaciar Carrito</button>
          )}
        </div>

        {/* Resumen */}
        <div className="order-summary">
          <h3>Resumen del pedido</h3>

          <div className="delivery-options">
            <button className="delivery-selected">Envío</button>
            <button>Retiro</button>
          </div>

          <div className="price-summary">
            <div className="line">
              <span>Subtotal:</span>
              <span>${subtotal.toLocaleString()}</span>
            </div>
            <div className="line">
              <span>Descuentos:</span>
              <span>-${discount.toLocaleString()}</span>
            </div>
          </div>

          <div className="coupon">
            <input 
              type="text" 
              placeholder="Ingresá tu código" 
              value={coupon}
              onChange={(e) => setCoupon(e.target.value)}
            />
            <button>Agregar</button>
          </div>

          <div className="total">
            <strong>Total:</strong> ${total.toLocaleString()}
          </div>

          <button onClick={handleCheckout} className="checkout-btn">Finalizar compra</button>
          <button className="continue-shopping">Seguir comprando</button>
        </div>

      </div>
    </div>
  );
}

export default Carrito;
